var HORSE_RAW={"n":796,"f":15,"mn":[-33.2,-4.2,-192.4],"mx":[34.6,207.8,134.9],"p":"","i":""};
/* Cheval 3D de démonstration (modèle low-poly d'exemple three.js), décodé en mémoire. */
var HORSE=(function(R){
  function dec(s){var b=atob(s),u=new Uint8Array(b.length);for(var k=0;k<b.length;k++)u[k]=b.charCodeAt(k);return u.buffer}
  var q=new Int16Array(dec(R.p)),idx=new Uint16Array(dec(R.i)),n=R.n,F=R.f,frames=[];
  var H=R.mx[1]-R.mn[1],cx=(R.mx[0]+R.mn[0])/2,cz=(R.mx[2]+R.mn[2])/2;
  for(var f=0;f<F;f++){var a=new Float32Array(n*3);for(var k=0;k<n*3;k++){var c=k%3,v=(q[f*n*3+k]+32768)/65535*(R.mx[c]-R.mn[c])+R.mn[c];
    a[k]=c===0?(v-cx)/H:c===1?(v-R.mn[1])/H:(v-cz)/H}frames.push(a)}
  function lerp(t,out){t=((t%1)+1)%1;var x=t*F,i0=Math.floor(x)%F,i1=(i0+1)%F,w=x-Math.floor(x),A=frames[i0],B=frames[i1];
    for(var k=0;k<n*3;k++)out[k]=A[k]+(B[k]-A[k])*w;return out}
  function sample(count,seed){var s=seed||7;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646}
    var V=frames[0],T=idx.length/3,cum=new Float32Array(T),tot=0;
    for(var t=0;t<T;t++){var a=idx[t*3]*3,b=idx[t*3+1]*3,c=idx[t*3+2]*3;
      var ux=V[b]-V[a],uy=V[b+1]-V[a+1],uz=V[b+2]-V[a+2],vx=V[c]-V[a],vy=V[c+1]-V[a+1],vz=V[c+2]-V[a+2];
      var X=uy*vz-uz*vy,Y=uz*vx-ux*vz,Z=ux*vy-uy*vx;tot+=Math.sqrt(X*X+Y*Y+Z*Z)/2;cum[t]=tot}
    var tri=new Uint16Array(count),bary=new Float32Array(count*2);
    for(var k=0;k<count;k++){var r=rnd()*tot,lo=0,hi=T-1;while(lo<hi){var m=(lo+hi)>>1;if(cum[m]<r)lo=m+1;else hi=m}
      tri[k]=lo;var u=rnd(),v=rnd();if(u+v>1){u=1-u;v=1-v}bary[k*2]=u;bary[k*2+1]=v}
    return {tri:tri,bary:bary,count:count}}
  function points(S,V,out){for(var k=0;k<S.count;k++){var t=S.tri[k]*3,a=idx[t]*3,b=idx[t+1]*3,c=idx[t+2]*3,u=S.bary[k*2],v=S.bary[k*2+1],w=1-u-v;
      out[k*3]=V[a]*w+V[b]*u+V[c]*v;out[k*3+1]=V[a+1]*w+V[b+1]*u+V[c+1]*v;out[k*3+2]=V[a+2]*w+V[b+2]*u+V[c+2]*v}return out}
  return {n:n,F:F,idx:idx,frames:frames,lerp:lerp,sample:sample,points:points};
})(HORSE_RAW);
